#!/usr/bin/env python3
import rclpy
from multi_teleop.base import InputInterfaceNode
import tkinter as tk
from tkinter import font
import yaml
import os

class GuiNode(InputInterfaceNode):
    def __init__(self):
        # We need to load config BEFORE calling super().__init__ 
        # to know our axis/button names.
        
        # Temporary node to read parameter
        temp_node = rclpy.create_node('temp_gui_loader')
        temp_node.declare_parameter('config_file', '')
        config_path = temp_node.get_parameter('config_file').value
        temp_node.destroy_node()
        
        self._axis_configs = []
        self._button_configs = []
        
        if config_path and os.path.exists(config_path):
            try:
                with open(config_path, 'r') as f:
                    config = yaml.safe_load(f)
                    gui_cfg = config.get('gui_controls', {})
                    self._axis_configs = gui_cfg.get('axes', [])
                    self._button_configs = gui_cfg.get('buttons', [])
            except Exception as e:
                print(f"Failed to load GUI config: {e}")
        
        axis_names = [a['name'] for a in self._axis_configs] or ['dummy_axis']
        button_names = [b['name'] for b in self._button_configs] or ['dummy_button']
        
        super().__init__('gui_node', axis_names, button_names)
        self.declare_parameter('config_file', config_path or '')
        
        self._axes_values = [0.0] * len(axis_names)
        self._buttons_values = [0] * len(button_names)
        
        # UI Setup
        self.root = tk.Tk()
        self.root.title("Antigravity Teleop Dashboard")
        self.root.configure(bg='#222222')
        
        self.custom_font = font.Font(family="Courier", size=10, weight="bold")
        
        # Viridis Palette
        self.colors = {
            'bg': '#222222',
            'axis': '#21918c',   # Green
            'button': '#3b528b', # Blue
            'active': '#fde725', # Yellow
            'text': '#ffffff'
        }

        self._setup_ui()
        
    def _setup_ui(self):
        # Main container
        main_frame = tk.Frame(self.root, bg=self.colors['bg'], padx=20, pady=20)
        main_frame.pack(expand=True, fill='both')
        
        # Axes Section
        tk.Label(main_frame, text="--- AXES ---", bg=self.colors['bg'], fg=self.colors['active'], font=self.custom_font).grid(row=0, column=0, columnspan=2, pady=(0, 10))
        
        self.sliders = []
        for i, cfg in enumerate(self._axis_configs):
            row = (i // 2) + 1
            col = i % 2
            
            frame = tk.Frame(main_frame, bg=self.colors['bg'], padx=10, pady=5)
            frame.grid(row=row, column=col, sticky='nsew')
            
            tk.Label(frame, text=cfg['name'], bg=self.colors['bg'], fg=self.colors['text'], font=self.custom_font).pack()
            
            scale = tk.Scale(frame, from_=cfg['min'], to=cfg['max'], 
                            resolution=0.01, orient=tk.HORIZONTAL,
                            bg=self.colors['bg'], fg=self.colors['axis'],
                            troughcolor='#333333', highlightthickness=0,
                            length=150, font=self.custom_font,
                            command=lambda val, idx=i: self._on_axis_change(idx, val))
            scale.set(0.0)
            scale.pack()
            self.sliders.append(scale)

        # Buttons Section
        btn_start_row = ((len(self._axis_configs) + 1) // 2) + 2
        tk.Label(main_frame, text="--- BUTTONS ---", bg=self.colors['bg'], fg=self.colors['active'], font=self.custom_font).grid(row=btn_start_row, column=0, columnspan=2, pady=(20, 10))
        
        for i, cfg in enumerate(self._button_configs):
            row = btn_start_row + 1 + (i // 3)
            col = i % 3
            
            is_toggle = cfg.get('toggle', False)
            
            btn = tk.Button(main_frame, text=cfg['name'], 
                           bg=self.colors['button'], fg=self.colors['text'],
                           activebackground=self.colors['active'],
                           font=self.custom_font, width=12,
                           relief=tk.FLAT, pady=5)
            
            if is_toggle:
                # Toggle behavior
                btn.configure(command=lambda idx=i, b=btn: self._on_button_toggle(idx, b))
            else:
                # Momentary behavior
                btn.bind('<ButtonPress-1>', lambda e, idx=i: self._on_button_press(idx))
                btn.bind('<ButtonRelease-1>', lambda e, idx=i: self._on_button_release(idx))
            
            btn.grid(row=row, column=col, padx=5, pady=5)

    def _on_axis_change(self, idx, val):
        self._axes_values[idx] = float(val)
        self.update_and_publish()

    def _on_button_toggle(self, idx, btn):
        self._buttons_values[idx] = 1 if self._buttons_values[idx] == 0 else 0
        new_color = self.colors['active'] if self._buttons_values[idx] == 1 else self.colors['button']
        btn.configure(bg=new_color)
        self.update_and_publish()

    def _on_button_press(self, idx):
        self._buttons_values[idx] = 1
        self.update_and_publish()

    def _on_button_release(self, idx):
        self._buttons_values[idx] = 0
        self.update_and_publish()

    def update_and_publish(self):
        self.publish_input(self._axes_values, self._buttons_values)

def main(args=None):
    rclpy.init(args=args)
    node = GuiNode()
    
    def ros_loop():
        rclpy.spin_once(node, timeout_sec=0)
        node.root.after(10, ros_loop)
        
    node.root.after(10, ros_loop)
    try:
        node.root.mainloop()
    except KeyboardInterrupt:
        pass
    finally:
        node.destroy_node()
        rclpy.shutdown()

if __name__ == '__main__':
    main()
